import {
  format,
  isBefore,
  isSameDay,
  isSameMinute,
  isSameYear,
  isToday,
} from 'date-fns';
import {
  createIntl,
  createIntlCache,
  FormatDateOptions,
  IntlShape,
} from 'react-intl';

import { getRegionalFormat } from '@dynatrace-sdk/user-preferences';

import { Timeframe, TimeDetails } from '../../core/types/time.js';
import {
  TIMEFRAME_EXPRESSION,
  parseTime,
} from '../../core/utils/timeParser.js';
import { messages } from '../../forms/forms-core/time/timeParser.js';

const DATE_YEAR_SEPARATOR = ', ';

/**
 * returns expression in e.g. 'Last 5 minutes' format.
 */
function formatRelativeToNow(
  expression: string,
  prefix: 'future' | 'past',
  intl: IntlShape,
): string {
  const [, offsetString, unit] = expression.match(TIMEFRAME_EXPRESSION) ?? [];
  const offset = Math.abs(parseInt(offsetString));

  if (offset === 0) {
    return intl.formatMessage(messages.now);
  }

  const timeExpression = messages[unit as keyof typeof messages];
  if (timeExpression) {
    return intl.formatMessage(timeExpression, { prefix, offset });
  }

  return intl.formatMessage(messages.invalid);
}

/**
 * returns expression or formatted date time if format is iso8601.
 */
function formatDetails(details: TimeDetails): string {
  return details.type === 'expression'
    ? details.normalized
    : format(details.date, 'yyyy-MM-dd HH:mm');
}

/**
 *  return formatted relative expression for given time details.
 */
function formatRelativeExpressions(
  from: TimeDetails,
  to: TimeDetails,
  intl: IntlShape,
): string | undefined {
  if (to.normalized === 'now' && from.normalized === 'now') {
    return intl.formatMessage(messages.invalid);
  }

  if (to.normalized === 'now') {
    return formatRelativeToNow(from.normalized, 'past', intl);
  } else if (from.normalized === 'now') {
    return formatRelativeToNow(to.normalized, 'future', intl);
  }
}

/**
 * return proper display string for given timeframe.
 */
export function formatTimeframe(
  { from, to = 'now' }: Timeframe,
  intl: IntlShape,
): string {
  const fromDetails = parseTime(from);
  const toDetails = parseTime(to);

  if (!fromDetails || !toDetails) {
    return intl.formatMessage(messages.invalid);
  }

  let formatted: string | undefined;
  if (fromDetails.type === 'expression' && toDetails.type === 'expression') {
    formatted = formatRelativeExpressions(fromDetails, toDetails, intl);
  }

  return (
    formatted ??
    `${formatDetails(fromDetails)} ${intl.formatMessage(
      messages.to,
    )} ${formatDetails(toDetails)}`
  );
}

/**
 * Utility function that facilitates the formatting of a timeframe
 * The function creates the from-string and to-string respectively and returns
 * the timeframe parts as an array of strings. The IntlShape passed to the
 * function is used to determine the language, while the IntlShape created
 * in the function (intlTimeFormat) is used to determine the type of time
 * display.
 *
 * @param from - Start date in the timeframe
 * @param to - End date in the timeframe
 * @param intl - Intl object
 * @returns an array of timeframe parts.
 */
export function formatTimeframeToParts(
  from: Date,
  to: Date,
  intl: IntlShape,
): string | [string, string, string] {
  const cache = createIntlCache();
  const locale = getRegionalFormat();
  const intlTimeFormat = createIntl({ locale, messages: {} }, cache);

  const now = new Date();
  const isNowInTimeframe = isBefore(from, now) && !isBefore(to, now);
  const _to = isNowInTimeframe ? now : to;

  const yearFormatOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
  };
  const dateFormatOptions: Intl.DateTimeFormatOptions = {
    month: 'short',
    day: '2-digit',
  };
  const timeFormatOptions: Intl.DateTimeFormatOptions = {
    hour: '2-digit',
    minute: '2-digit',
  };

  const formatOptions = {
    yearFormatOptions,
    dateFormatOptions,
    timeFormatOptions,
  };

  const fromStr = getFromString(from, _to, intl, intlTimeFormat, formatOptions);
  const toStr = getToString(from, _to, intl, intlTimeFormat, formatOptions);

  const separator = intl.formatMessage(messages.to);

  return [fromStr, separator, toStr];
}

const getFromString = (
  from: Date,
  to: Date,
  intl: IntlShape,
  intlTimeFormat: IntlShape,
  formatOptions: {
    dateFormatOptions: FormatDateOptions;
    yearFormatOptions: FormatDateOptions;
    timeFormatOptions: FormatDateOptions;
  },
) => {
  const currentDate = new Date();

  const date = isToday(from)
    ? intl.formatMessage(messages.today)
    : intlTimeFormat.formatDate(from, formatOptions.dateFormatOptions);

  const year =
    isSameYear(from, currentDate) ||
    (isSameYear(from, to) && !isSameDay(from, to))
      ? ''
      : intlTimeFormat.formatDate(from, formatOptions.yearFormatOptions) +
        DATE_YEAR_SEPARATOR;

  const time = intlTimeFormat.formatDate(from, formatOptions.timeFormatOptions);

  return `${date}${DATE_YEAR_SEPARATOR}${year}${time}`;
};

const getToString = (
  from: Date,
  to: Date,
  intl: IntlShape,
  intlTimeFormat: IntlShape,
  formatOptions: {
    dateFormatOptions: FormatDateOptions;
    yearFormatOptions: FormatDateOptions;
    timeFormatOptions: FormatDateOptions;
  },
) => {
  const currentDate = new Date();

  let date =
    intlTimeFormat.formatDate(to, formatOptions.dateFormatOptions) +
    DATE_YEAR_SEPARATOR;
  if (isSameDay(from, to) || isSameMinute(to, currentDate)) {
    date = '';
  } else if (isToday(to)) {
    date = intl.formatMessage(messages.today) + DATE_YEAR_SEPARATOR;
  }

  const year =
    (isSameYear(to, currentDate) && isSameYear(from, to)) ||
    isSameDay(to, from) ||
    isSameDay(to, currentDate)
      ? ''
      : intlTimeFormat.formatDate(to, formatOptions.yearFormatOptions) +
        DATE_YEAR_SEPARATOR;

  const time = isSameMinute(to, currentDate)
    ? intl.formatMessage(messages.now)
    : intlTimeFormat.formatDate(to, formatOptions.timeFormatOptions);

  return `${date}${year}${time}`;
};

/**
 * Formats a plain date-based timeframe into a string, for display.
 * @param from - Start date in the timeframe
 * @param to - End date in the timeframe
 * @param intl - Intl object
 * @returns the formatted string
 */
export function formatTimeframePlain(
  from: Date,
  to: Date,
  intl: IntlShape,
): string {
  const timeframeParts = formatTimeframeToParts(from, to, intl);
  return typeof timeframeParts === 'string'
    ? timeframeParts
    : timeframeParts.join(' ');
}
